"""Hand-written and small-table sections of the Prompt Bazaar (used by gen_prompts.py).

Each section: (category, default tool, default kind, items)
Each item: (title, summary, prompt, output[, tool[, kind]])
"""

S = []


def sec(cat, tool, kind, items):
    S.append((cat, tool, kind, items))


