# ── Health & Fitness (10 goals + 10 diets) ─────────────────────────────────
HEALTH_NOTE = "\nGeneral wellness information, not medical advice. If you have a health condition, are pregnant, or take medication, check with a doctor first."
GOALS = ['fat loss', 'muscle gain', 'beginner strength', 'running a first 5K', 'home workouts with no equipment', 'better flexibility and mobility',
         'back-friendly core strength', 'fitness after 40', 'busy-schedule 20-minute workouts', 'improving posture for desk workers']
DIETS = ['vegetarian Indian', 'high-protein vegetarian', 'vegan', 'budget-friendly', 'eggetarian', 'Mediterranean-style', 'diabetes-friendly (doctor-approved plan first)', 'student hostel', 'weight-loss calorie deficit', 'balanced family']
sec('Health & Fitness', 'Any chatbot', 'text', [
    ('%s workout plan' % g.capitalize(), 'A 4-week %s plan with progression and form cues.' % g,
     "Create a 4-week workout plan for %s.\nMe: [AGE], [FITNESS LEVEL], [DAYS PER WEEK] days, [MINUTES] per session, equipment: [LIST], injuries or limits: [LIST].\nFor each day: warm-up, exercises with sets, reps and rest, simple form cues, and a cool-down. Add weekly progression and signs I should rest.%s" % (g, HEALTH_NOTE),
     "A four-week day-by-day plan with sets, reps, form cues, progression and recovery signals.")
    for g in GOALS
] + [
    ('%s meal plan' % d.split(' (')[0].capitalize(), 'A 7-day %s meal plan with a grocery list.' % d.split(' (')[0],
     "Create a 7-day %s meal plan.\nMe: [AGE], [GOAL], about [CALORIES OR 'estimate for me'] per day, foods I avoid: [LIST], cooking time: [MINUTES] per meal, budget: [AMOUNT].\nTable: Day | Breakfast | Lunch | Snack | Dinner, with rough protein per meal. Then a grocery list grouped by section and 3 prep-ahead tips.%s" % (d, HEALTH_NOTE),
     "A seven-day table with approximate protein, a grouped grocery list and meal-prep tips.")
    for d in DIETS
])

